create or replace function public.premium_set_platform_audience(p_audience_type text) returns public.premium_accounts language plpgsql security definer set search_path to 'public' as $$ declare result_row public.premium_accounts; begin if auth.uid() is null then raise exception using message='not_authenticated'; end if; if p_audience_type not in ('boys','girls') then raise exception using message='invalid_audience_type'; end if; if not (public.premium_is_system_admin(auth.uid()) or exists(select 1 from public.premium_entitlements e where e.user_id=auth.uid() and e.is_active=true and e.expires_at>now())) then raise exception using message='active_package_required'; end if; update public.premium_accounts set presentation_audience_type=p_audience_type,updated_at=now() where user_id=auth.uid() returning * into result_row; if result_row.user_id is null then raise exception using message='account_not_found'; end if; return result_row; end; $$; grant execute on function public.premium_set_platform_audience(text) to authenticated;